{"hypotheses": [
  {
    "name": "Resilient Profitability in Low Volatility Regimes",
    "mechanism": "Combining operating profitability (OperProf), gross profitability (GP), and excluding high systematic volatility exposures (betaVIX) should isolate resilient, high-quality firms whose excess returns are less threatened during periods of market calm, capturing persistent mispricing of high-quality, low-risk stocks.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 0.5, "primitive": "GP"},
        {"weight": -0.5, "primitive": "betaVIX"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "OperProf", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Momentum-Adjusted Asset Growth",
    "mechanism": "Netting recent 12-month momentum (Mom12m) against asset growth (AssetGrowth) should overweight stocks where price trends are not driven by aggressive balance sheet expansion, mitigating the risk of chasing overvalued growth and capturing truly persistent winners.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -0.5, "primitive": "AssetGrowth"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.80,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Intangible Value Divergence",
    "mechanism": "By combining intangible-adjusted book-to-market (IntanBM), patent intensity (PatentsRD), and subtracting traditional book-to-market (BM), this composite captures undervaluation of innovation and intellectual capital that is not reflected in basic value strategies.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntanBM"},
        {"weight": 0.5, "primitive": "PatentsRD"},
        {"weight": -1.0, "primitive": "BM"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Cautious Capital Allocators",
    "mechanism": "Stocks with high cash productivity (CashProd) and low net equity financing (NetEquityFinance), while avoiding high payout yields (PayoutYield), represent disciplined capital allocators who reinvest efficiently and are less exposed to short-termism, resulting in higher future returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CashProd"},
        {"weight": -1.0, "primitive": "NetEquityFinance"},
        {"weight": -0.5, "primitive": "PayoutYield"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "CashProd", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Analyst Disagreement Surprise",
    "mechanism": "Taking the difference between changes in analyst forecast dispersion (ForecastDispersion) and realized earnings surprises (EarningsSurprise) highlights situations where the market is caught off-guard by earnings events relative to analyst uncertainty, exploiting mispricings from information shocks.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": -1.0, "primitive": "EarningsSurprise"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "EarningsSurprise", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 15
  },
  {
    "name": "Liquidity Contrarian Quality",
    "mechanism": "Long quality (MS) and short illiquidity (Illiquidity) while overweighting stocks with positive realized-to-implied volatility spreads (RIVolSpread) captures high-quality companies that are temporarily shunned due to liquidity shock overreactions, allowing contrarian entry.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "MS"},
        {"weight": -0.5, "primitive": "Illiquidity"},
        {"weight": 0.5, "primitive": "RIVolSpread"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "Illiquidity", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.90,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Industry Leader Dispersion",
    "mechanism": "Combining industry momentum (IndMom) and industry concentration by sales (Herf), while offsetting with high firm-level return skewness (ReturnSkew), isolates leading firms in concentrated, trending industries that are not simply lucky outliers, capturing sustainable advantage.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IndMom"},
        {"weight": 0.5, "primitive": "Herf"},
        {"weight": -0.5, "primitive": "ReturnSkew"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.80,
    "expected_decay_half_life_months": 28
  },
  {
    "name": "Reversal of Overvalued Capital Raisers",
    "mechanism": "Shorting recent share issuers (ShareIss1Y), high market leverage (Leverage), and adding short-term reversal (STreversal) targets stocks that have aggressively raised capital and become overextended, profiting from subsequent mean reversion in their excessive valuations.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "ShareIss1Y"},
        {"weight": -0.5, "primitive": "Leverage"},
        {"weight": 1.0, "primitive": "STreversal"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "STreversal", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 14
  }
]}
